<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {Puzzle,ShieldCheck,PanelTop,ArrowRight,FileCheck,Check,TriangleAlert,LockKeyhole,RotateCcw,ChevronRight,Monitor,ScanLine} from '@lucide/vue'
const props=defineProps<{scenario:string;inspection?:boolean}>()
const opened=ref(false),details=ref(false),revoked=ref(false),target=ref(''),report=ref(false),tab=ref('Checks'),consent=ref(false),accepted=ref(false)
const blocked=computed(()=>revoked.value||['Permission denied','Disconnected','Changed version','Stopped','Error'].includes(props.scenario))
watch(()=>props.scenario,()=>{revoked.value=false;report.value=false;accepted.value=false;consent.value=false})
watch(target,()=>{report.value=false;accepted.value=false;consent.value=false})
function run(){if(target.value&&!blocked.value){report.value=true;tab.value='Checks';accepted.value=false;consent.value=false}}
</script>
<template><section class="ap"><header class="ap-head"><div><p class="pv-eyebrow">{{inspection?'PREVIEW CHECKS · PV-07 / r1':'ADDON WORKSPACE · PV-06 / r1'}}</p><h1>{{inspection?'Review what you built':'A focused space for your addons'}}</h1></div><span class="pv-badge">Fixture · no live permissions</span></header>
<div class="ap-shell"><aside class="ap-sidebar"><p class="pv-eyebrow">WORKSPACE</p><div class="ap-workspace"><span class="ap-avatar">M</span><div><strong>Studio project</strong><p>Local workspace</p></div></div><p class="pv-eyebrow">EXTENSIONS</p><button class="ap-nav" @click="opened=true"><Puzzle :size="18"/><span>Preview inspector</span><ChevronRight :size="15"/></button><div class="ap-sidebar-bottom"><ShieldCheck :size="17"/><span>Isolated by the host</span></div></aside>
<div class="ap-content"><header class="ap-bar"><div><Puzzle :size="17"/><span>Preview inspector</span><span class="pv-badge">0.1.0</span></div><button class="btn" :aria-expanded="details" @click="details=!details"><ShieldCheck :size="15"/>Page access</button></header>
