<div v-else class="ap-inspector"><div class="ap-title"><div><span class="pv-eyebrow">ISOLATED ADDON CONTENT</span><h2>Preview inspector</h2></div><FileCheck :size="25"/></div><div class="ap-target"><label for="preview-target">Preview target</label><div><select id="preview-target" v-model="target" class="input"><option value="">Choose a registered preview</option><option value="home">Studio homepage · revision 3</option><option value="settings">Project settings · revision 2</option></select><button class="btn btn-primary" :disabled="!target||scenario==='Read only'" @click="run"><ScanLine :size="16"/>Run checks</button></div></div>
<div v-if="!report" class="ap-empty ap-await"><Monitor :size="32"/><h3>Select a preview to begin</h3><p>Results stay attached to that exact revision.</p></div>
<template v-else><div class="ap-report-heading"><div><h3>{{target==='home'?'Studio homepage':'Project settings'}}</h3><span class="pv-muted">{{target==='home'?'Revision 3':'Revision 2'}} · Fixture report 001</span></div><span class="pv-badge">Review ready</span></div><nav class="ap-tabs" aria-label="Inspection evidence"><button v-for="name in ['Checks','Visual evidence','Console','Model opinion']" :key="name" :aria-pressed="tab===name" @click="tab=name">{{name}}</button></nav>
<div v-if="tab==='Checks'" class="ap-checks"><div v-for="check in ['Target revision matches','No horizontal overflow at 1280 px','Primary action has an accessible name']" :key="check"><Check :size="17"/><span>{{check}}</span><span class="pv-muted">Fixture pass</span></div><div><TriangleAlert :size="17"/><span>Small-screen spacing needs human review</span><span class="pv-muted">Review</span></div></div>
<div v-else-if="tab==='Visual evidence'" class="ap-evidence"><div class="ap-mini"><span>STUDIO / PREVIEW</span><h3>Make room for your next idea.</h3><div class="ap-mini-grid"><div/><div/><div/></div></div><p class="pv-muted">Illustrative fixture, not a captured screenshot. Live reports will show captured evidence with target revision and dimensions.</p></div>
<div v-else-if="tab==='Console'" class="ap-note">Fixture console: no recorded errors. This sample does not establish the state of your real preview.</div>
<div v-else class="ap-note"><strong>Model review has not run</strong><p>Model opinions stay separate from deterministic checks. No model service or paid API is connected here.</p></div>
<footer class="ap-review"><div><h3>Your review</h3><p>Acceptance records the visual result for this revision. It grants no permissions.</p></div><div v-if="accepted" class="ap-accepted" role="status"><Check :size="18"/>Fixture acceptance recorded for this revision</div><template v-else><label><input v-model="consent" type="checkbox"/>I reviewed this revision and its evidence</label><div class="ap-review-buttons"><button class="btn" @click="accepted=false;consent=false;tab='Checks'">Needs changes</button><button class="btn btn-primary" :disabled="!consent" @click="accepted=true">Accept this revision</button></div></template></footer></template></div>
<footer class="ap-frame-label"><LockKeyhole :size="12"/>Isolated page · host controls remain outside</footer></div></div></section></template>
